/// One thing that happened on a to-do: what someone said or did, or what the hub saw happen (proposal 3.6, 6.1
/// Activity). Clients draw it; they work out nothing from it.
public nonisolated struct TodoTimelineEntry: Codable, Hashable, Sendable {
    /// Unique within the to-do's timeline, and the same on every read while the hub keeps what it was read from.
    /// Opaque to clients (spec/fixtures/todo-rounds/README.md says how the hub forms it).
    public var id: String
    public var type: String
    /// When it happened; a run line's latest turn, or since when the run works for a live line that has no turn yet.
    public var at: String
    public var actor: TodoActor
    /// Words someone wrote, as they wrote them: the owner's instruction or answer, a relay, a run's latest summary or
    /// what it does now, a decision's choice, a report, a review's note; absent when nobody wrote any. Today's stores
    /// keep a few of the hub's own sentences in the place of such words, in the language they were written in
    /// (spec/fixtures/todo-rounds/README.md "Judgement calls"): a failed start's that names no error, a turn's that
    /// ended without a summary, a permission or plan card's answer.
    public var text: String?
    /// The option the owner chose, on an answer whose text is what they said in a conversation rather than the option
    /// itself; absent otherwise.
    public var choice: String?
    /// What an answer or a decision answers, in the words it was asked in; absent when nothing says.
    public var question: String?
    /// Why, in the words of whoever answered or decided; absent when nobody said.
    public var reason: String?
    /// What the hub says about it, as a key and its arguments (spec/fixtures/todo-rounds/README.md "Line keys");
    /// absent when text says it all.
    public var line: TodoLine?
    /// The run it is about: the run a message or a relay reached, a run line's run, the run that started, ended or
    /// failed; absent when the hub does not know which (a run line without one is "A run").
    public var run: TodoRunRef?
    /// The id of the to-do's open ask this is (an OwnerAsk id of its view); absent once that ask is no longer open.
    public var ask: String?
    public var via: String?
    /// Where the owner's instruction stands; only on instructions.
    public var state: String?
    /// The id of the to-do's decision it was read from (GET /api/v1/todos/{id}/decisions).
    public var decision: String?
    /// The decision that replaced it, on an entry read from a decision a later one superseded; absent while it holds.
    public var supersededBy: String?
    /// How many of its run's turns in the round the line stands for; on run and interrupted lines, absent on a live
    /// line before its first turn ends.
    public var turns: Int?
    /// The run works now: only on a run line of the latest round. Written only when true.
    public var live: Bool?

    public init(id: String = "", type: String = "", at: String = "", actor: TodoActor = TodoActor(), text: String? = nil, choice: String? = nil, question: String? = nil, reason: String? = nil, line: TodoLine? = nil, run: TodoRunRef? = nil, ask: String? = nil, via: String? = nil, state: String? = nil, decision: String? = nil, supersededBy: String? = nil, turns: Int? = nil, live: Bool? = nil) {
