        self.at = at
        self.actor = actor
        self.text = text
        self.choice = choice
        self.question = question
        self.reason = reason
        self.line = line
        self.run = run
        self.ask = ask
        self.via = via
        self.state = state
        self.decision = decision
        self.supersededBy = supersededBy
        self.turns = turns
        self.live = live
    }

    enum CodingKeys: String, CodingKey {
        case id
        case type
        case at
        case actor
        case text
        case choice
        case question
        case reason
        case line
        case run
        case ask
        case via
        case state
        case decision
        case supersededBy = "superseded_by"
        case turns
        case live
    }

    public init(from decoder: Decoder) throws {
