        self.id = (try? c.decodeIfPresent(String.self, forKey: .id)) ?? ""
        self.type = (try? c.decodeIfPresent(String.self, forKey: .type)) ?? ""
        self.at = (try? c.decodeIfPresent(String.self, forKey: .at)) ?? ""
        self.actor = (try? c.decodeIfPresent(TodoActor.self, forKey: .actor)) ?? TodoActor()
        self.text = try? c.decodeIfPresent(String.self, forKey: .text)
        self.choice = try? c.decodeIfPresent(String.self, forKey: .choice)
        self.question = try? c.decodeIfPresent(String.self, forKey: .question)
        self.reason = try? c.decodeIfPresent(String.self, forKey: .reason)
        self.line = try? c.decodeIfPresent(TodoLine.self, forKey: .line)
        self.run = try? c.decodeIfPresent(TodoRunRef.self, forKey: .run)
        self.ask = try? c.decodeIfPresent(String.self, forKey: .ask)
        self.via = try? c.decodeIfPresent(String.self, forKey: .via)
        self.state = try? c.decodeIfPresent(String.self, forKey: .state)
        self.decision = try? c.decodeIfPresent(String.self, forKey: .decision)
        self.supersededBy = try? c.decodeIfPresent(String.self, forKey: .supersededBy)
